-- schema.sql 을 먼저 Run 한 뒤 이 파일을 Run 하세요. 여러 번 실행해도 됩니다(같은 id는 덮어씀).

on conflict (id) do update set name = excluded.name, category = excluded.category, address = excluded.address,
  road_address = excluded.road_address, phone = excluded.phone, url = excluded.url, lat = excluded.lat, lng = excluded.lng;

on conflict (name) do update set type = excluded.type, aliases = excluded.aliases, kind = excluded.kind, shape = excluded.shape;
